Here's a basic Node.js script you can run locally:

```javascript
const https = require('https');

const URL = process.argv[2];
const PORT = process.argv[3];

const verify = async () => {
  const result = await https.get(URL, {
    hostname: URL.hostname,
    port: String(PORT).padStart(2, '0'),
  });

  if (!result.statusCode === 200) {
    console.log('Error: ' + result.statusCode + ' (' + result.statusText + ')');
    process.exit(1);
  }

  // Check HTTPS certificate
  const cert = await result.getResponseHeader('X-Custom-SSL-Certificate');
  if (!Object.prototype.hasOwnProperty.call(cert, 'issuer')) {
    console.log('Warning: ' + URL + ' has invalid cert');
    process.exit(1);
  }
};

verify();
```

